import{_ as a,o,c as t,a0 as s}from"./chunks/framework.ChlVJx0I.js";const m=JSON.parse('{"title":"The llama-refresh extension is dropped","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0048-drop-llama-refresh.md","filePath":"adr/0048-drop-llama-refresh.md","lastUpdated":1794522309000}'),r={name:"adr/0048-drop-llama-refresh.md"};function n(d,e,i,l,h,c){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="the-llama-refresh-extension-is-dropped" tabindex="-1">The llama-refresh extension is dropped <a class="header-anchor" href="#the-llama-refresh-extension-is-dropped" aria-label="Permalink to &quot;The llama-refresh extension is dropped&quot;">​</a></h1><p>The operator asked for the llama-refresh extension to be removed. It existed to repair the context window a pi session holds for a local llama.cpp model: pi caches the window the provider reported, a model that wakes or a server that relaunches with a different <code>n_ctx</code> leaves the session with a stale value, and the extension&#39;s two heal moments compared the catalog before and after one forced refresh and re-applied the model when the window moved. The heals were working (the operator&#39;s session logs carry the extension&#39;s <code>llama window:</code> report lines); the drop removes a working feature on the operator&#39;s judgment, not a broken one.</p><p>Dropped: the extension (<code>extensions/llama-refresh/</code>), its docs page, its tests, and the <code>e2e:llama-refresh</code> manifest script. Moved: the context-window-cap record the extension read (<code>extensions/shared/context-window-cap.ts</code>) now lives in the context-cap extension (<code>extensions/context-cap/cap.ts</code>), which is its only remaining owner; it stays a process-global <code>Symbol.for</code> record, so a double-loaded copy of the extension still sees the cap. Kept: <code>tests/shared/llama-mock-router.mjs</code>, the mock llama.cpp router the output-starvation e2e still runs against.</p><p>This ADR supersedes <a href="/pi-extensions/adr/0019-llama-refresh-self-heals-the-fallback-window.html">ADR 0019</a>, <a href="/pi-extensions/adr/0027-the-live-catalog-comparison-heals-the-window.html">ADR 0027</a>, and <a href="/pi-extensions/adr/0031-a-same-model-re-select-is-read-from-the-transcript.html">ADR 0031</a>. The superseded files stay in the index, marked superseded, as the record of why those designs were made and what they guaranteed.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>A session that resolves a local llama.cpp model while it is asleep, or whose server relaunches mid-session, keeps the window it resolved: nothing re-reads the catalog or re-applies the model. The Context window cap still clamps that window at every boundary the window is consumed.</li><li>The operator&#39;s pi loads the package with no llama-refresh exclusion or setting to remove: the extension registered no flag and read no setting, and its <code>/llama-window</code> command simply stops existing.</li><li>The context-cap extension&#39;s behavior is unchanged.</li></ul>',6)])])}const f=a(r,[["render",n]]);export{m as __pageData,f as default};
